C = {
 'ctx': ("Contesto storico e sociale:", "dagli anni Settanta e Ottanta emerge l'interdipendenza globale con i suoi limiti di sviluppo (crisi energetiche, riscaldamento globale)."),
 'inf': ("Rivoluzione informatica:", "sviluppo dei primi computer e nascita del World Wide Web (WWW), cioè la rete mondiale dei siti, che cambia la comunicazione globale."),
 'post': ("Società postindustriale:", "passaggio dalla produzione manifatturiera all'economia dei servizi e della “società dell'informazione”."),
 'cond': ("La condizione postmoderna:", "fine delle grandi ideologie novecentesche, sfiducia nel progresso assoluto e nascita del concetto di “postmoderno” (teorizzato da Lyotard nel 1979)."),
 'geo': ("Cambiamenti geopolitici:", "fine del blocco sovietico, caduta del Muro di Berlino, nascita dell'Unione Europea ed eventi drammatici come l'attacco alle Twin Towers nel 2001."),
 'mondo': ("Un mondo interconnesso:", "sviluppo della globalizzazione, delle multinazionali e della rete, accompagnato da movimenti di contestazione ecologista e sociale."),
 'pm': ("Postmoderno nelle arti:", "abbattimento delle barriere tra cultura “alta” e “bassa”, forte libertà sperimentale e recupero di citazioni dal passato."),
 'glob': ("Dimensione globale:", "l'arte si apre a mercati e culture non occidentali attraverso grandi mostre internazionali (per esempio Les Magiciens de la terre, 1989)."),
 'neo': ("Neoespressionismo in Germania:", "ritorno alla pittura espressiva e accesa dopo il concettualismo. Esponenti principali: Georg Baselitz (noto per i dipinti capovolti) e Anselm Kiefer (temi storici e miti germanici)."),
 'rich': ("Il realismo freddo:", "Gerhard Richter esplora il rapporto ambiguo tra pittura e fotografia."),
 'tra': ("La Transavanguardia italiana:", "movimento teorizzato da Achille Bonito Oliva che promuove un atteggiamento “nomade” e un citazionismo eclettico (attingere a diversi stili del passato)."),
 'esp': ("Esponenti italiani:", "Sandro Chia, Francesco Clemente (unione di stili occidentali e orientali) e Mimmo Paladino (ispirazione ad archetipi mediterranei)."),
 'metro': ("Nascita nelle metropoli:", "il fenomeno nasce a New York dalle scritte sui vagoni dei treni e sui muri, legandosi alla cultura hip hop."),
 'har': ("Keith Haring:", "celebre per le sue icone stilizzate e “immagini radianti” (come il Radiant Baby), caratterizzate da una linea continua e un'energia vitale."),
 'sguardo': ("Lo sguardo della fotografia:", "diventa forma espressiva monumentale e concettuale (Robert Mapplethorpe con la perfezione formale, Bernd e Hilla Becher con le tipologie industriali, Andreas Gursky con le monumentali immagini digitali della società dei consumi)."),
 'video': ("Video Art e installazioni:", "sviluppo delle immagini in movimento con le videosculture di Nam June Paik, le riflessioni sul tempo di Bill Viola e l'immaginario metamorfico di Matthew Barney."),
 'cons': ("Consumo culturale di massa:", "l'artista diventa una celebrità mediatica (fenomeno radicato a partire da Andy Warhol)."),
 'koons': ("Jeff Koons:", "crea sculture monumentali ispirate a giocattoli e oggetti di consumo in stile kitsch."),
 'prov': ("Provocazione e Spazio:", "Maurizio Cattelan dissacra il sistema dell'arte con ironia, mentre Anish Kapoor lavora sul rapporto tra spazio, materia e superfici specchianti (per esempio Cloud Gate)."),
 'hightech': ("Il linguaggio High-Tech:", "protagonismo della tecnologia visibile, delle strutture ingegneristiche e dei materiali industriali lasciati scoperti."),
 'piano': ("Renzo Piano:", "unisce la tecnologia ingegneristica alla sostenibilità ambientale e alla luminosità degli spazi (per esempio Centre Pompidou a Parigi, New York Times Building)."),
 'deco': ("Decostruttivismo e nuovi stili:", "frammentazione delle geometrie tradizionali e nascita di nuove forme fluide grazie ai software di progettazione digitale."),
 'gehry': ("Frank O. Gehry:", "concepisce l'architettura come una scultura monumentale dinamica, utilizzando superfici ondulate in titanio e lamiera (per esempio Museo Guggenheim di Bilbao)."),
 'hadid': ("Zaha Hadid:", "pioniera dell'architettura parametrica, caratterizzata da forme fluide, curve continue e cemento leggero che eliminano i tradizionali angoli retti (per esempio Museo MAXXI di Roma, cioè Museo nazionale delle arti del XXI secolo)."),
}

